-- Starter catalog for Arganista (generated by scripts/gen-seed.ts).
-- Run in Supabase → SQL Editor after 0001_shop.sql. Safe to re-run: existing slugs are skipped.
begin;

with p as (
  insert into products (slug, category, ingredients, badges, name, tagline, description, how_to, key_ingredients, tint, position)
  values ('huile-argan-cosmetique-bio', 'huiles', array['argan']::text[], array['best']::text[], '{"fr":"Huile d''Argan Cosmétique Bio","en":"Organic Cosmetic Argan Oil","ar":"زيت الأركان التجميلي العضوي"}'::jsonb, '{"fr":"L''or liquide du Souss, pressé à froid","en":"Cold-pressed liquid gold from the Souss","ar":"الذهب السائل من سوس، معصور على البارد"}'::jsonb, '{"fr":"Notre huile d''argan pure, pressée à froid par les femmes de la coopérative. Riche en vitamine E et en acides gras essentiels, elle nourrit, assouplit et illumine la peau, les cheveux et les ongles.","en":"Our pure argan oil, cold-pressed by the women of the cooperative. Rich in vitamin E and essential fatty acids, it nourishes, softens and brightens skin, hair and nails.","ar":"زيت أركان نقي معصور على البارد من طرف نساء التعاونية. غني بفيتامين E والأحماض الدهنية الأساسية، يغذّي البشرة والشعر والأظافر ويمنحها نعومة وإشراقًا."}'::jsonb, '{"fr":"Visage : 2 à 3 gouttes matin et soir sur peau propre. Cheveux : quelques gouttes sur les pointes, ou en bain d''huile avant le shampoing.","en":"Face: 2–3 drops morning and night on clean skin. Hair: a few drops on the ends, or as a pre-shampoo oil treatment.","ar":"للوجه: 2 إلى 3 قطرات صباحًا ومساءً على بشرة نظيفة. للشعر: بضع قطرات على الأطراف أو كحمّام زيت قبل الشامبو."}'::jsonb, '{"fr":"100 % huile d''argan (Argania spinosa) bio","en":"100% organic argan oil (Argania spinosa)","ar":"زيت أركان عضوي 100٪"}'::jsonb, '#f1e3d6', 0)
  on conflict (slug) do nothing
  returning id
), v as (
  insert into product_variants (product_id, code, label, price, in_stock, image_url, position)
  select p.id, x.code, x.label, x.price, true, x.image_url, x.pos from p, (values
    ('30ml', '30 ml', 89::numeric, null, 0),
    ('100ml', '100 ml', 199::numeric, null, 1)
  ) as x(code, label, price, image_url, pos)
  returning 1
)
insert into product_images (product_id, url, position)
select p.id, x.url, x.pos from p, (values
  ('/images/catalog/argan-100ml.jpg', 0),
  ('/images/catalog/argan-gamme.jpg', 1)
) as x(url, pos);

with p as (
  insert into products (slug, category, ingredients, badges, name, tagline, description, how_to, key_ingredients, tint, position)
  values ('huile-pepins-figue-de-barbarie-bio', 'huiles', array['figue']::text[], array['best']::text[], '{"fr":"Huile de Pépins de Figue de Barbarie Bio","en":"Organic Prickly Pear Seed Oil","ar":"زيت بذور التين الشوكي العضوي"}'::jsonb, '{"fr":"Le soin anti-âge le plus précieux du désert","en":"The desert''s most precious anti-ageing oil","ar":"أثمن زيت لمكافحة الشيخوخة من الصحراء"}'::jsonb, '{"fr":"Il faut près d''une tonne de fruits pour obtenir un litre de cette huile rare. Exceptionnellement riche en vitamine E et en stérols, elle lisse les traits, atténue les ridules et redonne éclat au teint.","en":"Nearly a tonne of fruit is needed for one litre of this rare oil. Exceptionally rich in vitamin E and sterols, it smooths features, softens fine lines and restores radiance.","ar":"يتطلّب لتر واحد من هذا الزيت النادر قرابة طن من الثمار. غني جدًا بفيتامين E والستيرولات، ينعّم الملامح ويخفّف الخطوط الدقيقة ويعيد للبشرة إشراقها."}'::jsonb, '{"fr":"Appliquer 2 à 3 gouttes le soir sur le visage, le cou et le contour des yeux, en massant délicatement.","en":"Apply 2–3 drops in the evening to face, neck and eye area, massaging gently.","ar":"ضعي 2 إلى 3 قطرات مساءً على الوجه والعنق ومحيط العينين مع تدليك لطيف."}'::jsonb, '{"fr":"100 % huile de pépins de figue de barbarie (Opuntia ficus-indica) bio","en":"100% organic prickly pear seed oil (Opuntia ficus-indica)","ar":"زيت بذور التين الشوكي العضوي 100٪"}'::jsonb, '#e2e8df', 1)
  on conflict (slug) do nothing
  returning id
), v as (
  insert into product_variants (product_id, code, label, price, in_stock, image_url, position)
  select p.id, x.code, x.label, x.price, true, x.image_url, x.pos from p, (values
    ('15ml', '15 ml', 249::numeric, '/images/catalog/figue-15ml.jpg', 0),
    ('30ml', '30 ml', 449::numeric, '/images/catalog/figue-30ml.jpg', 1)
  ) as x(code, label, price, image_url, pos)
  returning 1
)
