select p.id, x.url, x.pos from p, (values
  ('/images/catalog/figue-15ml.jpg', 0),
  ('/images/catalog/figue-30ml.jpg', 1),
  ('/images/catalog/figue-gamme.jpg', 2)
) as x(url, pos);

with p as (
  insert into products (slug, category, ingredients, badges, name, tagline, description, how_to, key_ingredients, tint, position)
  values ('serum-anti-rides-rose', 'serums', array['rose','argan']::text[], array['best']::text[], '{"fr":"Sérum Anti-Rides à la Rose","en":"Rose Anti-Wrinkle Serum","ar":"سيروم مضاد للتجاعيد بالورد"}'::jsonb, '{"fr":"Fermeté et douceur à la rose de Damas","en":"Firmness and softness with Damask rose","ar":"شدّ ونعومة بالورد الدمشقي"}'::jsonb, '{"fr":"Un sérum huileux léger qui associe la rose et l''argan pour raffermir la peau, atténuer les rides et laisser un parfum floral délicat.","en":"A light oil serum pairing rose and argan to firm the skin, soften wrinkles and leave a delicate floral scent.","ar":"سيروم زيتي خفيف يجمع الورد والأركان لشدّ البشرة وتخفيف التجاعيد مع رائحة زهرية رقيقة."}'::jsonb, '{"fr":"Matin et/ou soir, appliquer quelques gouttes sur le visage et le cou propres, puis masser en mouvements ascendants.","en":"Morning and/or night, apply a few drops to clean face and neck and massage upwards.","ar":"صباحًا و/أو مساءً، ضعي بضع قطرات على الوجه والعنق النظيفين ودلّكي بحركات صاعدة."}'::jsonb, '{"fr":"Rose, huile d''argan","en":"Rose, argan oil","ar":"الورد، زيت الأركان"}'::jsonb, '#f4e1de', 2)
