with p as (
  insert into products (slug, category, ingredients, badges, name, tagline, description, how_to, key_ingredients, tint, position)
  values ('serum-anti-age-argan-figue-vitamine-e', 'serums', array['argan','figue']::text[], array['new']::text[], '{"fr":"Sérum Anti-Âge Argan, Figue de Barbarie & Vitamine E","en":"Anti-Ageing Serum — Argan, Prickly Pear & Vitamin E","ar":"سيروم مضاد للشيخوخة — أركان، تين شوكي وفيتامين E"}'::jsonb, '{"fr":"Le trio régénérant","en":"The regenerating trio","ar":"الثلاثي المجدّد"}'::jsonb, '{"fr":"L''alliance de l''argan, de la figue de barbarie et de la vitamine E pour régénérer la peau, préserver son élasticité et lutter contre les signes de l''âge.","en":"Argan, prickly pear and vitamin E combine to regenerate skin, preserve elasticity and fight the signs of ageing.","ar":"مزيج الأركان والتين الشوكي وفيتامين E لتجديد البشرة والحفاظ على مرونتها ومحاربة علامات التقدّم في السن."}'::jsonb, '{"fr":"Le soir, appliquer 3 à 4 gouttes sur le visage et le cou, avant votre crème.","en":"In the evening, apply 3–4 drops to face and neck before your moisturiser.","ar":"مساءً، ضعي 3 إلى 4 قطرات على الوجه والعنق قبل الكريم."}'::jsonb, '{"fr":"Huile d''argan, huile de pépins de figue de barbarie, vitamine E","en":"Argan oil, prickly pear seed oil, vitamin E","ar":"زيت الأركان، زيت بذور التين الشوكي، فيتامين E"}'::jsonb, '#ece3d4', 3)
