  values ('creme-visage-rose', 'visage', array['rose']::text[], array[]::text[], '{"fr":"Crème Visage à la Rose","en":"Rose Face Cream","ar":"كريم الوجه بالورد"}'::jsonb, '{"fr":"Hydratation douce au quotidien","en":"Gentle everyday hydration","ar":"ترطيب لطيف يومي"}'::jsonb, '{"fr":"Une crème douce à la rose qui hydrate, apaise et préserve la douceur de la peau. Sa texture fond délicatement et laisse le teint frais.","en":"A gentle rose cream that hydrates, soothes and preserves the skin''s softness. Its texture melts in and leaves the complexion fresh.","ar":"كريم لطيف بالورد يرطّب ويهدّئ ويحافظ على نعومة البشرة. قوامه يذوب برقة ويترك البشرة منتعشة."}'::jsonb, '{"fr":"Appliquer matin et soir sur le visage et le cou, en massant délicatement jusqu''à absorption.","en":"Apply morning and night to face and neck, massaging gently until absorbed.","ar":"ضعيه صباحًا ومساءً على الوجه والعنق مع تدليك لطيف حتى يمتصّ."}'::jsonb, '{"fr":"Eau de rose, glycérine","en":"Rose water, glycerin","ar":"ماء الورد، الغليسرين"}'::jsonb, '#f4e1de', 4)
