with p as (
  insert into products (slug, category, ingredients, badges, name, tagline, description, how_to, key_ingredients, tint, position)
  values ('huile-argan-alimentaire', 'terroir', array['argan']::text[], array[]::text[], '{"fr":"Huile d''Argan Alimentaire Torréfiée","en":"Toasted Culinary Argan Oil","ar":"زيت الأركان الغذائي المحمّص"}'::jsonb, '{"fr":"Pure et naturelle, au goût de noisette","en":"Pure and natural, with a nutty taste","ar":"نقي وطبيعي بنكهة البندق"}'::jsonb, '{"fr":"Obtenue à partir d''amandes d''argan légèrement torréfiées, cette huile au goût de noisette sublime salades, couscous, tajines et petits-déjeuners.","en":"Made from lightly toasted argan kernels, this nutty oil elevates salads, couscous, tagines and breakfasts.","ar":"مستخلص من لوز الأركان المحمّص قليلًا، بنكهة البندق التي ترتقي بالسلطات والكسكس والطاجين ووجبات الفطور."}'::jsonb, '{"fr":"À consommer cru : en filet sur vos plats, avec du pain ou mélangé au miel et aux amandes.","en":"Enjoy raw: drizzled over dishes, with bread, or mixed with honey and almonds.","ar":"يُستهلك نيئًا: على الأطباق، مع الخبز أو ممزوجًا بالعسل واللوز."}'::jsonb, '{"fr":"100 % huile d''argan torréfiée","en":"100% toasted argan oil","ar":"زيت أركان محمّص 100٪"}'::jsonb, '#ece3d4', 10)
  on conflict (slug) do nothing
  returning id
), v as (
  insert into product_variants (product_id, code, label, price, in_stock, image_url, position)
  select p.id, x.code, x.label, x.price, true, x.image_url, x.pos from p, (values
    ('250ml', '250 ml', 129::numeric, '/images/catalog/huile-alimentaire-250ml.jpg', 0),
    ('500ml', '500 ml', 229::numeric, '/images/catalog/huile-alimentaire-500ml.jpg', 1),
    ('1l', '1 L', 419::numeric, '/images/catalog/huile-alimentaire-1l.jpg', 2)
  ) as x(code, label, price, image_url, pos)
  returning 1
)
insert into product_images (product_id, url, position)
select p.id, x.url, x.pos from p, (values
  ('/images/catalog/huile-alimentaire-250ml.jpg', 0),
  ('/images/catalog/huile-alimentaire-gamme.jpg', 1),
  ('/images/catalog/huile-alimentaire-500ml.jpg', 2),
  ('/images/catalog/huile-alimentaire-1l.jpg', 3)
) as x(url, pos);

with p as (
  insert into products (slug, category, ingredients, badges, name, tagline, description, how_to, key_ingredients, tint, position)
  values ('amlou-beldi', 'terroir', array['argan']::text[], array[]::text[], '{"fr":"Amlou Beldi","en":"Traditional Amlou","ar":"أملو بلدي"}'::jsonb, '{"fr":"Amandes, argan et miel","en":"Almonds, argan and honey","ar":"لوز، أركان وعسل"}'::jsonb, '{"fr":"La pâte à tartiner traditionnelle du Souss : amandes grillées, huile d''argan et miel, broyés selon la recette d''antan.","en":"The traditional spread of the Souss: toasted almonds, argan oil and honey, ground the old-fashioned way.","ar":"الدهن التقليدي لسوس: لوز محمّص وزيت أركان وعسل، مطحونة على الطريقة القديمة."}'::jsonb, '{"fr":"À tartiner sur du pain, du msemen ou des crêpes au petit-déjeuner.","en":"Spread on bread, msemen or pancakes at breakfast.","ar":"يُدهن على الخبز أو المسمن أو البغرير في الفطور."}'::jsonb, '{"fr":"Amandes, huile d''argan, miel","en":"Almonds, argan oil, honey","ar":"لوز، زيت أركان، عسل"}'::jsonb, '#ece3d4', 11)
  on conflict (slug) do nothing
  returning id
), v as (
  insert into product_variants (product_id, code, label, price, in_stock, image_url, position)
  select p.id, x.code, x.label, x.price, true, x.image_url, x.pos from p, (values
    ('std', null, 99::numeric, null, 0)
  ) as x(code, label, price, image_url, pos)
  returning 1
)
insert into product_images (product_id, url, position)
select p.id, x.url, x.pos from p, (values
  ('/images/catalog/amlou-beldi.jpg', 0)
) as x(url, pos);

commit;
